package com.controldecortes.controller;
import com.controldecortes.domain.ActiveStatus;import com.controldecortes.dto.ApiDtos.*;import com.controldecortes.repository.*;import com.controldecortes.service.SettlementService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final SupplierRepository suppliers;private final CutRepository cuts;private final SettlementRepository settlements;private final SettlementService service;public DashboardController(SupplierRepository s,CutRepository c,SettlementRepository f,SettlementService ss){suppliers=s;cuts=c;settlements=f;service=ss;}@GetMapping public DashboardResponse get(Authentication auth){String owner=auth.getName().trim();OffsetDateTime from=YearMonth.now().atDay(1).atStartOfDay().atOffset(ZoneOffset.UTC),to=from.plusMonths(1);var current=settlements.findBySupplierOwnerIdAndSettledAtBetweenOrderBySettledAtDesc(owner,from,to);BigDecimal total=current.stream().map(x->x.getTotalAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);return new DashboardResponse(suppliers.countByOwnerId(owner),cuts.countByStatusAndOwner(ActiveStatus.ACTIVE,owner),current.size(),total,service.recent().stream().limit(5).toList());}}
